package fraymus.workspace;

import org.json.*;
import java.nio.*;
import java.nio.channels.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.awt.image.BufferedImage;
import java.io.*;

/**038 private camera journal. Same durable world/body IDs; no native physics authority. */
final class TabletopStore {
    static final String VERSION="tabletop-038-v1";
    private final Path root,file,lock;
    private final WorldLedger worlds;
    private final MetricObservationStore metrics;
    private final Map<String,Processor> processors=new HashMap<>();
    TabletopStore(Path project,WorldLedger worlds,MetricObservationStore metrics)throws Exception{this.worlds=worlds;this.metrics=metrics;root=project.resolve("tabletop-038");file=root.resolve("state.json");lock=root.resolve("state.lock");access(true,s->{for(Object raw:s.getJSONArray("runs")){var r=(JSONObject)raw;if(r.getString("status").equals("running"))r.put("status","interrupted").put("reason","Process ended; explicitly resume exact original frames and camera reference");}return null;});}
    static String identity(){var b=new StringBuilder(VERSION);for(Class<?> c:new Class<?>[]{TabletopStore.class,RigidTargetTracker.class,TabletopFilter.class,MatReferenceGuard.class,TabletopAnalysis.class})try(var in=c.getResourceAsStream(c.getSimpleName()+".class")){b.append(PerceptionStore.hash(in.readAllBytes()));}catch(Exception e){throw new IllegalStateException(e);}return MeasurementStore.hash(b.toString());}
    private interface Tx<T>{T apply(JSONObject s)throws Exception;}
    private synchronized <T>T access(boolean write,Tx<T> tx)throws Exception{
        Files.createDirectories(root);try(var channel=FileChannel.open(lock,StandardOpenOption.CREATE,StandardOpenOption.WRITE);var held=channel.lock()){
            JSONObject s;if(Files.exists(file)){if(Files.size(file)>16_000_000)throw new IllegalStateException("Tabletop history exceeds16MB; preserve/export");var e=new JSONObject(Files.readString(file));s=e.getJSONObject("payload");if(!VERSION.equals(e.getString("version"))||!WorldFrames.hash(s).equals(e.getString("sha256")))throw new IllegalStateException("Tabletop history checksum changed; originals preserved");}else s=new JSONObject().put("checks",new JSONArray()).put("runs",new JSONArray()).put("analyses",new JSONArray());
            T out=tx.apply(s);if(write){if(s.getJSONArray("runs").length()>24||s.getJSONArray("checks").length()>64||s.getJSONArray("analyses").length()>64)throw new IllegalStateException("Tabletop capacity reached; no pruning");byte[] bytes=new JSONObject().put("version",VERSION).put("sha256",WorldFrames.hash(s)).put("payload",s).toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>16_000_000)throw new IllegalStateException("Tabletop history capacity reached");var pending=file.resolveSibling("state.pending.json");try(var w=FileChannel.open(pending,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING,StandardOpenOption.WRITE)){var b=ByteBuffer.wrap(bytes);while(b.hasRemaining())w.write(b);w.force(true);}Files.move(pending,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}return out;
        }
    }
    private static JSONObject find(JSONArray a,String id){return MetricObservationStore.find(a,id);}
    private JSONObject geometry(String id)throws Exception{return WorldFrames.copy(find(metrics.state().getJSONArray("geometries"),id));}
    private static JSONObject summary(JSONObject r){var v=WorldFrames.copy(r);v.remove("trace");v.remove("seed");return v;}
    JSONObject state()throws Exception{return access(false,s->{var out=WorldFrames.copy(s);var runs=new JSONArray();for(Object raw:s.getJSONArray("runs"))runs.put(summary((JSONObject)raw));return out.put("runs",runs).put("version",VERSION).put("codeSha256",identity()).put("scope","One human-seeded rigid target; projected centre on declared mat, actual source seconds, model uncertainty. No semantic recognition, certified metrology or native action authority.");});}
    boolean busy()throws Exception{return access(false,s->{for(Object raw:s.getJSONArray("runs"))if(((JSONObject)raw).getString("status").equals("running"))return true;return false;});}
    JSONObject read(String id)throws Exception{return access(false,s->WorldFrames.copy(find(s.getJSONArray("runs"),id)));}
    private void current(JSONObject binding)throws Exception{var n=worlds.observe(binding.getString("worldId"));if(n.has("pending")||!n.getString("expectedHash").equals(binding.getString("expectedHash"))||n.getInt("expectedRevision")!=binding.getInt("expectedRevision"))throw new IllegalStateException("Native world changed or is owned; explicitly bind a new run");}
    private byte[] bytes(JSONObject frame)throws Exception{SpatialScene.keys(frame,"image","imageSha256","seconds");PlaneCalibration.bounded(frame.getDouble("seconds"),0,1_000_000);byte[] b=Base64.getDecoder().decode(frame.getString("image"));if(!PerceptionStore.hash(b).equals(frame.getString("imageSha256")))throw new IllegalStateException("Camera sample checksum differs");WorldObservationStore.decode(b);return b;}
    private JSONObject saveFrame(String id,int ordinal,JSONObject input)throws Exception{byte[] b=bytes(input);Path dir=root.resolve("frames").resolve(id);Files.createDirectories(dir);Path p=dir.resolve(ordinal+".image");if(Files.exists(p)){if(!Arrays.equals(Files.readAllBytes(p),b))throw new IllegalStateException("Original sample already exists with different bytes");}else{try(var out=FileChannel.open(p,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){var buffer=ByteBuffer.wrap(b);while(buffer.hasRemaining())out.write(buffer);out.force(true);}}var f=WorldFrames.copy(input);f.remove("image");f.put("bytes",b.length);Path meta=dir.resolve(ordinal+".meta.json");if(Files.exists(meta)){if(!new JSONObject(Files.readString(meta)).similar(f))throw new IllegalStateException("Original camera time/metadata changed");}else Files.writeString(meta,f.toString(),StandardOpenOption.CREATE_NEW);return f;}
    private BufferedImage pixels(String id,int ordinal,JSONObject ref)throws Exception{byte[] b=Files.readAllBytes(root.resolve("frames").resolve(id).resolve(ordinal+".image"));if(!PerceptionStore.hash(b).equals(ref.getString("imageSha256")))throw new IllegalStateException("Original camera sample changed");return WorldObservationStore.decode(b);}
    JSONObject check(JSONObject input)throws Exception{
        SpatialScene.keys(input,"geometryId","cameraKey","frame","pointA","pointB","lengthM","markA","markB","unit","source");var g=geometry(input.getString("geometryId"));var plane=new PlaneCalibration(g.getJSONObject("definition"));if(!plane.definition().getString("cameraKey").equals(input.getString("cameraKey")))throw new IllegalArgumentException("Camera key differs from plane");bytes(input.getJSONObject("frame"));var a=PlaneCalibration.point(input.getJSONArray("pointA"));var b=PlaneCalibration.point(input.getJSONArray("pointB"));if(!plane.inPlane(a[0],a[1])||!plane.inPlane(b[0],b[1]))throw new IllegalArgumentException("Tape reference points must be inside measured mat");String unit=input.getString("unit");double unitScale=switch(unit){case "in"->.0254;case "cm"->.01;case "m"->1;default->throw new IllegalArgumentException("Declare in,cm or m");};double markA=PlaneCalibration.bounded(input.getDouble("markA"),0,1000),markB=PlaneCalibration.bounded(input.getDouble("markB"),0,1000);double length=PlaneCalibration.bounded(input.getDouble("lengthM"),.01,1);if(Math.abs(Math.abs(markB-markA)*unitScale-length)>1e-8)throw new IllegalArgumentException("Tape mark/unit declaration disagrees with physical length");double actual=PlaneCalibration.distance(plane.project(a[0],a[1]),plane.project(b[0],b[1])),error=Math.abs(actual-length);if(input.getString("source").isBlank()||input.getString("source").length()>1500)throw new IllegalArgumentException("Declare independently read tape units/marks");String id=UUID.randomUUID().toString();var frame=saveFrame(id,0,input.getJSONObject("frame"));var record=new JSONObject().put("id",id).put("createdAt",Instant.now()).put("geometry",g).put("cameraKey",input.getString("cameraKey")).put("frame",frame).put("pointA",input.getJSONArray("pointA")).put("pointB",input.getJSONArray("pointB")).put("expectedM",length).put("measuredM",actual).put("absoluteErrorM",error).put("toleranceM",.005).put("passed",error<=.005).put("source",input.getString("source")).put("markA",markA).put("markB",markB).put("unit",unit);return access(true,s->{for(Object raw:s.getJSONArray("checks")){var old=(JSONObject)raw;if(old.getJSONObject("geometry").getString("sha256").equals(g.getString("sha256"))&&old.getJSONObject("frame").getString("imageSha256").equals(frame.getString("imageSha256")))throw new IllegalStateException("First independent tape check is immutable; use a new declared measurement/version");}s.getJSONArray("checks").put(record);return WorldFrames.copy(record);});
    }
    synchronized JSONObject start(JSONObject input)throws Exception{
        SpatialScene.keys(input,"worldId","expectedRevision","expectedHash","geometryId","checkId","cameraKey","bodyId","label","box","frame");var binding=new JSONObject();for(String k:List.of("worldId","expectedRevision","expectedHash"))binding.put(k,input.get(k));current(binding);var nativeState=worlds.observe(binding.getString("worldId"));ContactPhysics.dynamic(nativeState.getJSONObject("frame").getJSONArray("bodies"),input.getString("bodyId"));var g=geometry(input.getString("geometryId"));var plane=new PlaneCalibration(g.getJSONObject("definition"));if(!plane.definition().getString("cameraKey").equals(input.getString("cameraKey")))throw new IllegalArgumentException("Camera/plane differs");if(input.getString("label").isBlank()||input.getString("label").length()>80)throw new IllegalArgumentException("Declare a short human target label");var box=PixelTracker.Box.from(input.getJSONArray("box"));var frame=input.getJSONObject("frame");var first=WorldObservationStore.decode(bytes(frame));var checkRecord=access(false,state->WorldFrames.copy(find(state.getJSONArray("checks"),input.getString("checkId"))));var processor=new Processor(first,box,plane,frame.getDouble("seconds"),pixels(checkRecord.getString("id"),0,checkRecord.getJSONObject("frame")));if(!processor.guard.check(first).getBoolean("valid"))throw new IllegalStateException("Camera/mat differs from verified reference image; recalibrate");if(!plane.inPlane(box.x()+box.w()/2,box.y()+box.h()/2))throw new IllegalArgumentException("Target centre is outside marked mat plane");String id=UUID.randomUUID().toString();var seed=saveFrame(id,0,frame);
        var r=access(true,s->{for(Object raw:s.getJSONArray("runs"))if(Set.of("running","interrupted").contains(((JSONObject)raw).getString("status")))throw new IllegalStateException("Resume or Stop the current tabletop run first");var check=find(s.getJSONArray("checks"),input.getString("checkId"));if(!check.getBoolean("passed")||!check.getJSONObject("geometry").getString("sha256").equals(g.getString("sha256"))||!check.getString("cameraKey").equals(input.getString("cameraKey")))throw new IllegalStateException("Pass an independent tape check for this camera/plane first");var run=new JSONObject().put("id",id).put("nativeBinding",binding).put("geometry",g).put("check",check).put("cameraKey",input.getString("cameraKey")).put("bodyId",input.getString("bodyId")).put("label",input.getString("label")).put("labelSource","Human-guided, not automatic semantic recognition").put("box",input.getJSONArray("box")).put("seed",seed).put("status","running").put("createdAt",Instant.now()).put("codeSha256",identity()).put("generation",0).put("trace",new JSONArray()).put("completedFrames",0).put("sourceBytes",seed.getInt("bytes")).put("reason","Actual private source frames; one frame in flight");s.getJSONArray("runs").put(run);return WorldFrames.copy(run);});processors.put(id,processor);return summary(r);
    }
    private static final class Processor {
        final RigidTargetTracker tracker;final MatReferenceGuard guard;final TabletopFilter filter;final PlaneCalibration plane;final int width,height;
        Processor(BufferedImage first,PixelTracker.Box box,PlaneCalibration p,double seconds,BufferedImage reference){plane=p;width=first.getWidth();height=first.getHeight();tracker=new RigidTargetTracker(first,box);guard=new MatReferenceGuard(reference,p.definition());filter=new TabletopFilter(seconds,p.project(box.x()+box.w()/2,box.y()+box.h()/2));}
        JSONObject step(BufferedImage image,double seconds){if(image.getWidth()!=width||image.getHeight()!=height)throw new IllegalArgumentException("Camera dimensions changed; recalibrate");var reference=guard.check(image);var tracked=tracker.update(image);double[] measurement=null;if(tracked.getBoolean("accepted")){var point=PlaneCalibration.point(tracked.getJSONArray("point"));if(plane.inPlane(point[0],point[1]))measurement=plane.project(point[0],point[1]);}var estimate=filter.step(seconds,measurement,tracked.getBoolean("accepted")&&reference.getBoolean("valid"),plane.definition().getDouble("anchorSigmaM"));var position=PlaneCalibration.point(estimate.getJSONArray("positionM"));double scaleError=plane.definition().getDouble("scaleRelativeSigma")*Math.hypot(position[0],position[1]);estimate.put("radiusM",estimate.getDouble("radiusM")+scaleError).put("declaredScaleErrorM",scaleError);return new JSONObject().put("reference",reference).put("tracker",tracked).put("estimate",estimate);}
    }
    synchronized JSONObject frame(JSONObject input)throws Exception{
        SpatialScene.keys(input,"id","generation","ordinal","cameraKey","frame");String id=input.getString("id");var r=read(id);if(!r.getString("cameraKey").equals(input.getString("cameraKey")))throw new IllegalArgumentException("Camera clock/reference key changed; start a new run");current(r.getJSONObject("nativeBinding"));if(!r.getString("status").equals("running")||r.getInt("generation")!=input.getInt("generation"))throw new IllegalStateException("Stopped/stale tabletop execution generation");if(r.getInt("completedFrames")+1!=input.getInt("ordinal")||input.getInt("ordinal")>600)throw new IllegalStateException("Camera ordinal/capacity changed");if(!identity().equals(r.getString("codeSha256")))throw new IllegalStateException("Tabletop implementation changed; preserve original run");var p=processors.get(id);if(p==null)throw new IllegalStateException("Resume exact saved processor before new frames");var f=input.getJSONObject("frame");byte[] bytes=bytes(f);if(r.getLong("sourceBytes")+bytes.length>12_000_000){return access(true,state->{var limited=find(state.getJSONArray("runs"),id);limited.put("status","completed").put("reason","12MB original-sample capacity reached; last receipt retained, no pruning");processors.remove(id);return new JSONObject().put("run",summary(limited)).put("capacityReached",true);});}long start=System.nanoTime();JSONObject result;try{result=p.step(WorldObservationStore.decode(bytes),f.getDouble("seconds"));}catch(Exception e){processors.remove(id);access(true,state->{var failed=find(state.getJSONArray("runs"),id);failed.put("status","interrupted").put("reason",e.getMessage());return null;});throw e;}var ref=saveFrame(id,input.getInt("ordinal"),f);result.put("ordinal",input.getInt("ordinal")).put("frame",ref).put("bodyId",r.getString("bodyId")).put("processingMs",(System.nanoTime()-start)/1e6).put("receivedAt",Instant.now());
        return access(true,s->{var run=find(s.getJSONArray("runs"),id);if(!run.getString("status").equals("running")||run.getInt("generation")!=input.getInt("generation"))throw new IllegalStateException("Execution stopped before commit");run.getJSONArray("trace").put(result);run.put("completedFrames",input.getInt("ordinal")).put("sourceBytes",run.getLong("sourceBytes")+ref.getInt("bytes"));if(!result.getJSONObject("reference").getBoolean("valid")){run.put("status","recalibration-required").put("reason","Camera/mat anchors changed or are unobservable; no accepted metric update");processors.remove(id);}else if(input.getInt("ordinal")==600){run.put("status","completed").put("reason","Bounded600-frame observation complete");processors.remove(id);}return new JSONObject().put("run",summary(run)).put("latest",WorldFrames.copy(result));});
    }
    synchronized JSONObject stop(String id)throws Exception{var r=access(true,s->{var run=find(s.getJSONArray("runs"),id);if(!Set.of("running","interrupted").contains(run.getString("status")))throw new IllegalStateException("Run already settled");run.put("status","cancelled").put("generation",run.getInt("generation")+1).put("reason","Explicit Stop; original frames and measurements retained");return summary(run);});processors.remove(id);return r;}
    synchronized JSONObject resume(String id)throws Exception{var r=read(id);if(!Set.of("interrupted","cancelled").contains(r.getString("status")))throw new IllegalStateException("Only a stopped/interrupted run can resume");current(r.getJSONObject("nativeBinding"));if(!identity().equals(r.getString("codeSha256")))throw new IllegalStateException("Runtime identity differs from original run");var p=new Processor(pixels(id,0,r.getJSONObject("seed")),PixelTracker.Box.from(r.getJSONArray("box")),new PlaneCalibration(r.getJSONObject("geometry").getJSONObject("definition")),r.getJSONObject("seed").getDouble("seconds"),pixels(r.getJSONObject("check").getString("id"),0,r.getJSONObject("check").getJSONObject("frame")));for(Object raw:r.getJSONArray("trace")){var row=(JSONObject)raw;var result=p.step(pixels(id,row.getInt("ordinal"),row.getJSONObject("frame")),row.getJSONObject("frame").getDouble("seconds"));for(String key:List.of("reference","tracker","estimate")){var expected=WorldFrames.copy(row.getJSONObject(key));var actual=result.getJSONObject(key);expected.remove("processingMs");actual.remove("processingMs");if(!expected.similar(actual))throw new IllegalStateException("Exact tabletop replay prefix differs; originals preserved");}}
        int pendingOrdinal=r.getInt("completedFrames")+1;Path pendingMeta=root.resolve("frames").resolve(id).resolve(pendingOrdinal+".meta.json"),pendingPixels=root.resolve("frames").resolve(id).resolve(pendingOrdinal+".image");if(Files.exists(pendingMeta)!=Files.exists(pendingPixels))throw new IllegalStateException("Pending original sample is incomplete; preserve/export and start a new run");
        var out=access(true,s->{for(Object raw:s.getJSONArray("runs")){var o=(JSONObject)raw;if(o.getString("status").equals("running"))throw new IllegalStateException("Another tabletop run active");}var run=find(s.getJSONArray("runs"),id);run.put("status","running").put("generation",run.getInt("generation")+1).put("reason","Exact original tracker/filter prefix restored; capture only same camera clock/reference");return summary(run);});processors.put(id,p);int next=r.getInt("completedFrames")+1;Path meta=root.resolve("frames").resolve(id).resolve(next+".meta.json"),source=root.resolve("frames").resolve(id).resolve(next+".image");if(Files.exists(meta)||Files.exists(source)){if(!Files.exists(meta)||!Files.exists(source))throw new IllegalStateException("Pending original camera sample is incomplete; preserve/export and start a new run");var pending=new JSONObject(Files.readString(meta));pending.remove("bytes");pending.put("image",Base64.getEncoder().encodeToString(Files.readAllBytes(source)));frame(new JSONObject().put("id",id).put("generation",out.getInt("generation")).put("ordinal",next).put("cameraKey",r.getString("cameraKey")).put("frame",pending));return summary(read(id));}return out;}
    synchronized JSONObject finish(String id)throws Exception{var out=access(true,s->{var r=find(s.getJSONArray("runs"),id);if(!Set.of("running","cancelled").contains(r.getString("status"))||r.getInt("completedFrames")<5)throw new IllegalStateException("Finish requires at least five captured frames");r.put("status","completed").put("generation",r.getInt("generation")+1).put("reason","Recording ended explicitly; accuracy/task success is separately verified");return summary(r);});processors.remove(id);return out;}
    JSONObject analyse(JSONObject input)throws Exception{SpatialScene.keys(input,"id","kind","fromMark","toMark","references","profileId","source");if(input.getString("source").isBlank()||input.getString("source").length()>1500)throw new IllegalArgumentException("Declare independent physical/reference source");var run=read(input.getString("id"));return access(true,s->{JSONObject profile=input.has("profileId")?find(s.getJSONArray("analyses"),input.getString("profileId")):null;for(Object raw:s.getJSONArray("analyses")){var old=(JSONObject)raw;if(old.getString("runId").equals(run.getString("id"))&&old.getString("kind").equals(input.getString("kind")))throw new IllegalStateException("First analysis of this kind/run is immutable; preserve original result");}var result=TabletopAnalysis.compute(run,input,profile).put("id",UUID.randomUUID().toString()).put("createdAt",Instant.now()).put("source",input.getString("source"));s.getJSONArray("analyses").put(result);return WorldFrames.copy(result);});}
    JSONArray analyses(String id)throws Exception{return access(false,s->{var a=new JSONArray();for(Object raw:s.getJSONArray("analyses")){var v=(JSONObject)raw;if(v.getString("runId").equals(id))a.put(WorldFrames.copy(v));}return a;});}
    JSONObject image(String id,int ordinal)throws Exception{var r=read(id);if(ordinal<0||ordinal>r.getInt("completedFrames"))throw new IllegalArgumentException("Unknown captured frame");var ref=ordinal==0?r.getJSONObject("seed"):r.getJSONArray("trace").getJSONObject(ordinal-1).getJSONObject("frame");pixels(id,ordinal,ref);return new JSONObject().put("image",Base64.getEncoder().encodeToString(Files.readAllBytes(root.resolve("frames").resolve(id).resolve(ordinal+".image")))).put("reference",ref);}
    JSONObject understanding(String id)throws Exception{var r=read(id);var trace=r.getJSONArray("trace");var latest=trace.isEmpty()?null:trace.getJSONObject(trace.length()-1);var n=worlds.observe(r.getJSONObject("nativeBinding").getString("worldId"));JSONObject relation=new JSONObject();if(latest!=null){var pos=PlaneCalibration.point(latest.getJSONObject("estimate").getJSONArray("positionM"));var plane=new PlaneCalibration(r.getJSONObject("geometry").getJSONObject("definition"));var check=r.getJSONObject("check");double[] a=PlaneCalibration.point(check.getJSONArray("pointA")),b=PlaneCalibration.point(check.getJSONArray("pointB")),pa=plane.project(a[0],a[1]),pb=plane.project(b[0],b[1]);double dx=pb[0]-pa[0],dy=pb[1]-pa[1],t=((pos[0]-pa[0])*dx+(pos[1]-pa[1])*dy)/(dx*dx+dy*dy);relation.put("interpolatedTapeMark",check.getDouble("markA")+t*(check.getDouble("markB")-check.getDouble("markA"))).put("unit",check.getString("unit")).put("perpendicularOffsetM",Math.abs((pos[0]-pa[0])*dy-(pos[1]-pa[1])*dx)/Math.hypot(dx,dy)).put("meaning","Projected estimate relative to human-read tape marks; no automatic OCR or verified3D contact");var tracker=latest.getJSONObject("tracker");if(tracker.has("point"))relation.put("imageSideOfTape",tracker.getJSONArray("point").getDouble(0)>(a[0]+b[0])/2?"right":"left");}
        return new JSONObject().put("relation",relation).put("runId",id).put("nativeBinding",r.getJSONObject("nativeBinding")).put("nativeStale",!n.getString("expectedHash").equals(r.getJSONObject("nativeBinding").getString("expectedHash"))).put("target",r.getString("label")).put("labelSource",r.getString("labelSource")).put("cameraKey",r.getString("cameraKey")).put("status",r.getString("status")).put("completedFrames",r.getInt("completedFrames")).put("tapeCheck",r.getJSONObject("check")).put("latest",latest==null?JSONObject.NULL:latest).put("ageMs",latest==null?JSONObject.NULL:Math.max(0,System.currentTimeMillis()-Instant.parse(latest.getString("receivedAt")).toEpochMilli())).put("limits","Projected centre on declared mat plane; height/depth/contact unverified. Match score is not probability. Model uncertainty is not empirically calibrated. No native movement or physical action authority.");}
    synchronized JSONObject export(String id)throws Exception{var r=read(id);var images=new JSONArray();for(int i=0;i<=r.getInt("completedFrames");i++)images.put(image(id,i));return new JSONObject().put("schema",VERSION).put("run",r).put("understanding",understanding(id)).put("images",images).put("analyses",(Object)access(false,state->{var a=new JSONArray();for(Object raw:state.getJSONArray("analyses")){var v=(JSONObject)raw;if(v.getString("runId").equals(id))a.put(v);}return a;})).put("checkImage",Base64.getEncoder().encodeToString(Files.readAllBytes(root.resolve("frames").resolve(r.getJSONObject("check").getString("id")).resolve("0.image")))).put("scope","Private original camera samples. Explicit local export only; do not publish personal images.");}
}
